function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.businessLogic || {};

  let currentApplyProcess = null;
  let selectedStores = new Set();

  // 現在日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  const startDatetimeInput = container.querySelector('#start-datetime');
  if (startDatetimeInput) {
    startDatetimeInput.value = now.toISOString().slice(0, 16);
  }

  // DOM要素を取得
  const modelSelect = container.querySelector('#model-select');
  const storeList = container.querySelector('#store-list');
  const modelDetailsArea = container.querySelector('#model-details');
  const modelInfo = container.querySelector('#model-info');
  const validationResults = container.querySelector('#validation-results');
  const applyBtn = container.querySelector('#apply-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const progressArea = container.querySelector('#progress-area');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const logArea = container.querySelector('#log-area');
  const logContent = container.querySelector('#log-content');

  // モデル一覧を読み込み
  async function loadModels() {
    try {
      const models = await window.aivicApi.list(8); // 需要予測結果テーブル

      if (models && modelSelect) {
        // 検証済みモデルのみを表示（ステータスが「完了」のもの）
        const validatedModels = models.filter(m => m.予測ステータス === '完了');

        modelSelect.innerHTML = '<option value="">-- モデルを選択してください --</option>' +
          validatedModels.map(m => 
            `<option value="${m.予測結果ID}">${m.予測モデルバージョン} (精度: ${m.予測精度 || 'N/A'}%)</option>`
          ).join('');
      }
    } catch (error) {
      window.aivicNotify.error('モデル一覧の読み込みに失敗しました: ' + error.message);
    }
  }

  // 店舗一覧を読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ

      if (stores && storeList) {
        const activeStores = stores.filter(s => s.有効フラグ);
        storeList.innerHTML = activeStores.map(store => `
          <label style="display: flex; align-items: center; gap: 8px; margin-bottom: 8px; cursor: pointer;">
            <input type="checkbox" class="store-checkbox" value="${store.店舗ID}" style="margin: 0;">
            <span style="color: var(--text); font-size: 14px;">${store.店舗名} (${store.店舗コード})</span>
          </label>
        `).join('');

        // 店舗チェックボックスのイベントリスナーを追加
        const checkboxes = storeList.querySelectorAll('.store-checkbox');
        checkboxes.forEach(checkbox => {
          checkbox.addEventListener('change', function() {
            if (this.checked) {
              selectedStores.add(this.value);
            } else {
              selectedStores.delete(this.value);
            }
            updateApplyButtonState();
          });
        });
      }
    } catch (error) {
      window.aivicNotify.error('店舗一覧の読み込みに失敗しました: ' + error.message);
    }
  }

  // モデル詳細情報を表示
  async function showModelDetails(modelId) {
    try {
      const models = await window.aivicApi.list(8);
      if (!models) return;

      const model = models.find(m => m.予測結果ID === modelId);
      if (!model) return;

      if (modelInfo) {
        modelInfo.innerHTML = `
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
            <div>
              <div style="margin-bottom: 8px;"><strong>モデルバージョン:</strong> ${model.予測モデルバージョン}</div>
              <div style="margin-bottom: 8px;"><strong>予測精度:</strong> ${model.予測精度 || 'N/A'}%</div>
              <div style="margin-bottom: 8px;"><strong>作成日時:</strong> ${new Date(model.作成日時).toLocaleString()}</div>
            </div>
            <div>
              <div style="margin-bottom: 8px;"><strong>ステータス:</strong> ${model.予測ステータス}</div>
              <div style="margin-bottom: 8px;"><strong>対象商品:</strong> ${model.商品ID ? '個別商品' : '全商品'}</div>
              <div style="margin-bottom: 8px;"><strong>備考:</strong> ${model.備考 || 'なし'}</div>
            </div>
          </div>
        `;
      }

      if (modelDetailsArea) {
        modelDetailsArea.classList.remove('hidden');
      }

      // 検証結果を表示
      showValidationResults(model);
      updateApplyButtonState();
    } catch (error) {
      window.aivicNotify.error('モデル詳細の読み込みに失敗しました: ' + error.message);
    }
  }

  // 検証結果を表示
  function showValidationResults(model) {
    if (!validationResults) return;

    const accuracy = model.予測精度 || 0;
    const status = model.予測ステータス;

    let statusColor = 'var(--text-muted)';
    if (status === '完了') statusColor = 'var(--success)';
    else if (status === 'エラー') statusColor = 'var(--error)';

    validationResults.innerHTML = `
      <div style="padding: 16px; background: var(--bg-secondary); border-radius: 8px;">
        <h4 style="margin: 0 0 12px 0; color: var(--text);">検証結果</h4>
        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">
          <div>
            <div style="margin-bottom: 8px;">
              <span style="color: var(--text-muted);">予測精度:</span>
              <span style="color: ${accuracy >= 80 ? 'var(--success)' : accuracy >= 60 ? 'var(--warning)' : 'var(--error)'}; font-weight: bold;">
                ${accuracy}%
              </span>
            </div>
            <div style="margin-bottom: 8px;">
              <span style="color: var(--text-muted);">ステータス:</span>
              <span style="color: ${statusColor}; font-weight: bold;">${status}</span>
            </div>
          </div>
          <div>
            <div style="margin-bottom: 8px;">
              <span style="color: var(--text-muted);">適用可能:</span>
              <span style="color: ${status === '完了' ? 'var(--success)' : 'var(--error)'}; font-weight: bold;">
                ${status === '完了' ? '可能' : '不可'}
              </span>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  // 適用ボタンの状態を更新
  function updateApplyButtonState() {
    if (applyBtn) {
      const modelSelected = modelSelect && modelSelect.value;
      const storesSelected = selectedStores.size > 0;
      applyBtn.disabled = !modelSelected || !storesSelected || currentApplyProcess;
    }
  }

  // モデル適用処理
  async function applyModel() {
    if (currentApplyProcess) return;

    const modelId = modelSelect?.value;
    const startDatetime = startDatetimeInput?.value;

    if (!modelId || selectedStores.size === 0) {
      window.aivicNotify.error('モデルと店舗を選択してください');
      return;
    }

    try {
      currentApplyProcess = true;
      updateApplyButtonState();

      if (progressArea) progressArea.classList.remove('hidden');
      if (logArea) logArea.classList.remove('hidden');

      updateProgress(0, 'モデル適用を開始しています...');
      addLog('モデル適用処理を開始しました');

      // 選択されたモデルの詳細を取得
      const models = await window.aivicApi.list(8);
      const selectedModel = models.find(m => m.予測結果ID === modelId);

      if (!selectedModel) {
        throw new Error('選択されたモデルが見つかりません');
      }

      addLog(`モデル: ${selectedModel.予測モデルバージョン} を適用中...`);
      updateProgress(10, 'データを収集しています...');

      // 業務ロジックを使用してデータを収集・分析
      const storeIds = Array.from(selectedStores);
      let salesData = [];

      for (let i = 0; i < storeIds.length; i++) {
        const storeId = storeIds[i];
        addLog(`店舗 ${storeId} のデータを収集中...`);

        // 売上データを収集
        if (collectSalesData) {
          const storeSalesData = await collectSalesData(storeId, startDatetime);
          if (storeSalesData) {
            salesData = salesData.concat(storeSalesData);
          }
        }

        updateProgress(10 + (i + 1) / storeIds.length * 30, `店舗データ収集中... (${i + 1}/${storeIds.length})`);
      }

      addLog(`${salesData.length} 件の売上データを収集しました`);
      updateProgress(40, 'データを分析しています...');

      // データを商品別・店舗別に分類
      let productClassifiedData = salesData;
      let storeClassifiedData = salesData;

      if (classifySalesDataByProduct) {
        productClassifiedData = classifySalesDataByProduct(salesData);
        addLog('商品別データ分類が完了しました');
      }

      if (classifySalesDataByStore) {
        storeClassifiedData = classifySalesDataByStore(salesData);
        addLog('店舗別データ分類が完了しました');
      }

      updateProgress(60, '外部データを収集しています...');

      // 天候・イベント・季節データを収集
      let weatherData = [];
      let eventData = [];
      let seasonalData = [];

      if (collectWeatherData) {
        weatherData = await collectWeatherData(startDatetime);
        addLog(`天候データ ${weatherData.length} 件を収集しました`);
      }

      if (collectEventData) {
        eventData = await collectEventData(startDatetime);
        addLog(`イベントデータ ${eventData.length} 件を収集しました`);
      }

      if (collectSeasonalData) {
        seasonalData = await collectSeasonalData(startDatetime);
        addLog(`季節データ ${seasonalData.length} 件を収集しました`);
      }

      updateProgress(80, '相関分析を実行しています...');

      // 相関分析を実行
      let correlationResults = {};

      if (analyzeCorrelationSalesWeather) {
        correlationResults.weather = analyzeCorrelationSalesWeather(salesData, weatherData);
        addLog('売上-天候相関分析が完了しました');
      }

      if (analyzeCorrelationSalesEvent) {
        correlationResults.event = analyzeCorrelationSalesEvent(salesData, eventData);
        addLog('売上-イベント相関分析が完了しました');
      }

      if (analyzeCorrelationSalesSeason) {
        correlationResults.season = analyzeCorrelationSalesSeason(salesData, seasonalData);
        addLog('売上-季節相関分析が完了しました');
      }

      updateProgress(90, '適用結果を保存しています...');

      // 適用結果を保存
      const applyResult = {
        適用ID: Date.now().toString(),
        予測結果ID: modelId,
        適用日時: new Date().toISOString(),
        対象店舗: storeIds.join(','),
        適用ステータス: '完了',
        処理件数: salesData.length,
        相関分析結果: JSON.stringify(correlationResults),
        作成日時: new Date().toISOString()
      };

      await window.aivicApi.save(9, applyResult); // モデル適用履歴テーブル

      updateProgress(100, 'モデル適用が完了しました');
      addLog('モデル適用処理が正常に完了しました');

      window.aivicNotify.success('モデルの適用が完了しました');

    } catch (error) {
      addLog(`エラー: ${error.message}`);
      window.aivicNotify.error('モデル適用に失敗しました: ' + error.message);
    } finally {
      currentApplyProcess = false;
      updateApplyButtonState();
    }
  }

  // 適用処理をキャンセル
  function cancelApply() {
    if (currentApplyProcess) {
      currentApplyProcess = false;
      updateApplyButtonState();
      addLog('適用処理がキャンセルされました');
      window.aivicNotify.info('適用処理をキャンセルしました');
    }
  }

  // プログレスバーを更新
  function updateProgress(percent, message) {
    if (progressBar) {
      progressBar.style.width = `${percent}%`;
    }
    if (progressText) {
      progressText.textContent = message;
    }
  }

  // ログを追加
  function addLog(message) {
    if (logContent) {
      const timestamp = new Date().toLocaleTimeString();
      logContent.innerHTML += `<div>[${timestamp}] ${message}</div>`;
      logContent.scrollTop = logContent.scrollHeight;
    }
  }

  // イベントリスナーを設定
  if (modelSelect) {
    modelSelect.addEventListener('change', function() {
      if (this.value) {
        showModelDetails(this.value);
      } else {
        if (modelDetailsArea) modelDetailsArea.classList.add('hidden');
        updateApplyButtonState();
      }
    });
  }

  if (applyBtn) {
    applyBtn.addEventListener('click', applyModel);
  }

  if (cancelBtn) {
    cancelBtn.addEventListener('click', cancelApply);
  }

  // 初期データを読み込み
  loadModels();
  loadStores();
  updateApplyButtonState();
}
